import numpy as np

def feature(item, bins, capacity):
    """Remaining room after placing the item, divided by capacity (worst-fit residual: emptiest post-placement bin scores highest)."""
    cap = float(capacity)
    post = (np.asarray(bins, dtype=float) - float(item)) / cap
    return np.clip(post, -1.0, 1.0)

import numpy as np

def feature(item, bins, capacity):
    """Normalised bin age rank: i/max(k-1,1) - 0.5, oldest = -0.5, new empty bin = +0.5."""
    k = bins.shape[0]
    if k == 1:
        return np.zeros(1)
    return np.arange(k) / (k - 1) - 0.5

import numpy as np

def feature(item, bins, capacity):
    """Large-item-gated worst-fit: 1[item/capacity > 0.35] * (bins/capacity - 0.5)."""
    large = 1.0 if item / capacity > 0.35 else 0.0
    return large * (bins / capacity - 0.5)

import numpy as np

def feature(item, bins, capacity):
    """Worst-fit preference (0.5 - remaining/capacity) only when no bin fits exactly and item/capacity >= 0.35, else 0."""
    it = item / capacity
    r = bins / capacity
    if np.any(bins - item == 0) or it < 0.35:
        return np.zeros(len(bins))
    return 0.5 - r

import numpy as np

def feature(item, bins, capacity):
    """Age ramp weighted by how much room the bin has left: (2*rank/(k-1)-1) * (remaining/capacity)."""
    k = len(bins)
    if k == 1:
        return np.zeros(1)
    rank = np.linspace(-1.0, 1.0, k)
    fill = np.clip(bins / capacity, 0.0, 1.0)
    return rank * fill
